def avaliar_k(X, ks=range(2, 11)):
    """Roda o K-means para cada k, plota cotovelo e silhouette, devolve o k de maior silhouette."""
    wcss, sil = [], []
    for k in ks:
        km = KMeans(n_clusters=k, init='k-means++', n_init=10, random_state=SEED).fit(X)
        wcss.append(km.inertia_)                       # WCSS: quão compactos são os clusters
        sil.append(silhouette_score(X, km.labels_))    # silhouette: coesão frente à separação
    fig, ax = plt.subplots(1, 2)
    ax[0].plot(ks, wcss, 'o-'); ax[0].set(title='Método do cotovelo', xlabel='k', ylabel='WCSS')
    ax[1].plot(ks, sil, 'o-'); ax[1].set(title='Silhouette score', xlabel='k', ylabel='Score')
    for a in ax:
        a.grid(alpha=0.3)
    plt.tight_layout(); plt.show()
    return list(ks)[int(np.argmax(sil))], max(sil)


def perfil(dados, rotulos, variaveis):
    """Média de cada variável por cluster, na escala original, com o tamanho de cada grupo."""
    tab = dados.groupby(rotulos)[variaveis].mean().round(2)
    tab.insert(0, 'Registros', np.bincount(rotulos))
    return tab


def concordancia(tab):
    """Fração de registros no maior grupo de cada coluna de uma tabela cruzada."""
    return tab.values.max(axis=0).sum() / tab.values.sum()

